<template><div><div class="text-h5 q-mb-md">編輯保單</div><q-card><q-card-section><q-form class="q-gutter-md" @submit="form.put(route('admin.insurance-policies.update',policy.id))"><q-select v-model="form.insurance_company_id" :options="companies" label="保險公司" outlined emit-value map-options :error="!!form.errors.insurance_company_id" :error-message="form.errors.insurance_company_id" /><q-input v-model="form.policy_code" label="保單代號" outlined :error="!!form.errors.policy_code" :error-message="form.errors.policy_code" /><q-input v-model="form.name" label="保單名稱" outlined :error="!!form.errors.name" :error-message="form.errors.name" /><q-input v-model="form.version" label="版本" outlined /><q-input v-model="form.effective_date" type="date" label="生效日期" outlined stack-label /><q-toggle v-model="form.is_active" label="啟用" /><div class="row q-gutter-sm"><q-btn type="submit" color="primary" label="更新" :loading="form.processing" /><q-btn flat label="取消" @click="$inertia.visit(route('admin.insurance-policies.index'))" /></div></q-form></q-card-section></q-card></div></template><script setup lang="ts">import{useForm}from'@inertiajs/vue3';import AdminLayout from '../../Layouts/AdminLayout.vue';defineOptions({layout:AdminLayout});const props=defineProps<{policy:{id:number;insurance_company_id:number;policy_code:string;name:string;version:string;effective_date:string|null;is_active:boolean};companies:{value:number;label:string;is_active:boolean}[]}>();const form=useForm({insurance_company_id:props.policy.insurance_company_id,policy_code:props.policy.policy_code,name:props.policy.name,version:props.policy.version,effective_date:props.policy.effective_date,is_active:props.policy.is_active})</script>